    calc_title:        'Farm Audit — MINMAXapp',
    calc_h1:           '🔍 Farm Audit',
    calc_intro:        'Self-audit tools for poultry house systems, based on UGA (University of Georgia, Michael Czarick) methodology. All units are metric.',
